const lessons=[{"sentences":[{"speaker":"A","text":"Welcome today to our urban geography lecture about small green spaces in modern cities.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.919958333333334},{"speaker":"A","text":"Many planners overlook tiny empty lots because they prefer massive parks for recreation.","position":2,"audioStartSeconds":6.119958333333333,"audioEndSeconds":11.85525},{"speaker":"A","text":"However pocket parks offer incredible benefits if local residents need quiet places to relax.","position":3,"audioStartSeconds":12.05525,"audioEndSeconds":18.537208333333332},{"speaker":"A","text":"Urban developers usually plant native trees because these plants require very little extra water.","position":4,"audioStartSeconds":18.737208333333335,"audioEndSeconds":24.935666666666666},{"speaker":"A","text":"Researchers frequently measure air temperature because shaded areas reduce summer heat significantly.","position":5,"audioStartSeconds":25.135666666666665,"audioEndSeconds":31.308333333333334},{"speaker":"A","text":"If you visit a garden today you might notice comfortable wooden benches for visitors.","position":6,"audioStartSeconds":31.508333333333333,"audioEndSeconds":36.856291666666664},{"speaker":"A","text":"Another common feature is colorful flowers which attract local bees and butterflies.","position":7,"audioStartSeconds":37.05629166666667,"audioEndSeconds":42.520208333333336},{"speaker":"A","text":"When scientists study visitor habits they often conduct brief interviews near the entrance.","position":8,"audioStartSeconds":42.72020833333333,"audioEndSeconds":48.5965},{"speaker":"A","text":"Observers should always record the exact time because visitor numbers change throughout the day.","position":9,"audioStartSeconds":48.7965,"audioEndSeconds":54.50525},{"speaker":"A","text":"Morning hours typically attract elderly neighbors who enjoy reading under peaceful morning shadows.","position":10,"audioStartSeconds":54.70525,"audioEndSeconds":60.8135},{"speaker":"A","text":"By contrast afternoon periods bring energetic children after finishing their daily school classes.","position":11,"audioStartSeconds":61.0135,"audioEndSeconds":67.36541666666666},{"speaker":"A","text":"Supposing an observer wanted to count users carefully a handheld clicker helps enormously.","position":12,"audioStartSeconds":67.56541666666666,"audioEndSeconds":73.32691666666666},{"speaker":"A","text":"Please remember that safety matters most so you should always wear comfortable walking shoes.","position":13,"audioStartSeconds":73.52691666666666,"audioEndSeconds":79.15758333333333},{"speaker":"A","text":"Your final written report must include a detailed map highlighting every major seating area.","position":14,"audioStartSeconds":79.35758333333334,"audioEndSeconds":85.382875}],"questions":[{"prompt":"Primary plants: ______","answer":"native trees","evidenceSentence":4,"evidence":"native trees","explanation":"Người thuyết trình cho biết các nhà phát triển thường trồng cây bản địa."},{"prompt":"Temperature effect: reduce ______","answer":"summer heat","evidenceSentence":5,"evidence":"summer heat","explanation":"Các khu vực có bóng râm giúp giảm bớt cái nóng mùa hè."},{"prompt":"Seating type: wooden ______","answer":"benches","evidenceSentence":6,"evidence":"wooden benches","explanation":"Bài giảng nhắc đến những chiếc ghế bằng gỗ thoải mái."},{"prompt":"Afternoon visitors: ______","answer":"children","evidenceSentence":11,"evidence":"children","explanation":"Buổi chiều thu hút những đứa trẻ năng động sau giờ học."},{"prompt":"Counting tool: handheld ______","answer":"clicker","evidenceSentence":12,"evidence":"handheld clicker","explanation":"Máy đếm bấm tay giúp ích rất nhiều cho việc đếm số lượng người."},{"prompt":"Required map feature: major ______","answer":"seating area","evidenceSentence":14,"evidence":"seating area","explanation":"Báo cáo cuối cùng phải bao gồm một bản đồ chi tiết làm nổi bật mọi khu vực ngồi chính."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
